# Generated by Manimator. Render with:  manim -pqm scene.py ActionsLinearTransformationScene

from manim import *


class ActionsLinearTransformationScene(LinearTransformationScene):
    def construct(self):
        # Objects
        circle = Circle(radius=1)
        circle.set_stroke(RED)
        circle.set_fill(RED)
        circle.move_to([2, 1, 0])
        vector = Vector(direction=2 * RIGHT + UP)
        vector.set_color(WHITE)
        eq = MathTex(r"e^{i\pi} + 1 = 0", font_size=48)
        eq.set_color(WHITE)
        eq.move_to([-3, 2, 0])

        self.add_transformable_mobject(circle)
        self.add_vector(vector)

        # Animation
        self.play(Write(eq), run_time=1)
        self.add_foreground_mobject(eq)
        # Scene.play() keeps its own list in self.moving_mobjects, the same attribute
        # LinearTransformationScene reads; empty it so only the grid's objects move.
        self.moving_mobjects = []
        self.apply_matrix([[1, 1], [0, 1]], added_anims=[Indicate(vector)], run_time=3)
        self.moving_mobjects = []
        self.apply_inverse([[1, 1], [0, 1]], added_anims=[Indicate(vector)], run_time=3)
        self.moving_mobjects = []
        self.apply_nonlinear_transformation(
            lambda p: np.array([p[0] + np.sin(p[1]), p[1] + np.sin(p[0]), 0]),
            added_anims=[Indicate(vector)],
            run_time=3,
        )
